import { Component } from '@angular/core';
import { AdvancedSearch, Button, RowButton, RowButtonClickEvent, TablaComponent, TableDefinition } from '../../../shared/tabla/tabla.component';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
import { Router } from '@angular/router';
import { EstadoCuenta, EstadoCuentaDetalle } from '../../../models/estado.cuenta';
import { CREDITOS_ADVANCED_SEARCH } from '../../creditos/creditos.busqueda.avanzada';
import { CREDITOS_TABLE_HEADERS_BASIC } from '../../creditos/creditos.table.headers';

const TABLA_DEF:TableDefinition={
  emptyMsg:'La tabla esta vacía, realiza una busqueda para comenzar.',
  columns:[
    {
      key:'id',
      header:'Id Crédito',
    },
    {
      key:'estados_cuenta',
      header:'Saldo Vencido',
      subKey:'saldo_vencido',
      pipe:'currency'
    },
    {
      key:'estados_cuenta',
      header:'Vencido desde',
      subKey:'vencido_desde',
      pipe:'date'
    },
    {
      key:'estados_cuenta',
      header:'Pagos Vencidos',
      function:(estado:EstadoCuenta) => {
        return (estado.pagos_requeridos-estado.pagos_realizados).toString()
      },
    },
    ...CREDITOS_TABLE_HEADERS_BASIC,
  ]
}
const EDITAR_BUTTON:Button={
  style:{
    button:'btn btn-sm btn-info',
    icon:'bi bi-eye-fill'
  },
}

const ADVANCED_SEARCH:AdvancedSearch=[
  {
    label:'Ctd Pagos Vencidos',
    key:'estadosCuenta',
    type:'text',
    conditionals:[
      {
        key:'pagos_vencidos',
        operator:'=',
      },
    ]
  },
  ...CREDITOS_ADVANCED_SEARCH
]

@Component({
    selector: 'app-list-estado-cuentas',
    imports: [
        TablaComponent
    ],
    templateUrl: './list-estado-cuentas.component.html',
    styleUrl: './list-estado-cuentas.component.css'
})
export class ListEstadoCuentasComponent {
  tabla = TABLA_DEF
  edit=EDITAR_BUTTON
  advancedSearch= ADVANCED_SEARCH
  constructor(
    public creditoController:CreditoService,
    private router:Router,
  ){}

  onRowButtonClick(event:RowButtonClickEvent<Credito>){
    this.router.navigate(['/main/creditos/contratos/'+event.row.id])
  }
}
