import { Component } from '@angular/core';
import { Credito } from '../../../models/credito.model';
import { FormsModule } from '@angular/forms';
import { CreditoService } from '../../../controllers/credito.service';
import { UtilsService } from '../../../services/utils.service';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';
import {
  CobroModalidad,
  CreditoEventoCobro,
} from '../../../models/credito.evento.cobro';
import { ViewResumenCreditoComponent } from '../shared/view-resumen-credito/view-resumen-credito.component';
import { ViewPeriodosComponent } from '../shared/view-periodos/view-periodos.component';
import { ViewRelacionAbonosComponent } from '../shared/view-relacion-abonos/view-relacion-abonos.component';
import { ViewGestionesCobroComponent } from '../shared/view-gestiones-cobro/view-gestiones-cobro.component';
import { ViewResumenClienteComponent } from '../shared/view-resumen-cliente/view-resumen-cliente.component';
import { ViewRelacionConveniosComponent } from '../shared/view-relacion-convenios/view-relacion-convenios.component';
import { EjecucionCobroComponent } from '../../cobranza/ejecucion-cobro/ejecucion-cobro.component';
import { BuscadorCreditosComponent } from '../shared/buscador-creditos/buscador-creditos.component';
import { CollapsableComponent } from '../../../shared/collapsable/collapsable.component';
import { estadoCuenta } from '../../../services/documentosLegales/contratos/contrato_estado_de_cuenta.service';
import { UtilsEstadoCuentaService } from '../services/utils-estado-cuenta.service';
import { Permiso } from '../../../models/permiso.model';
import { UsuarioLogin } from '../../../auth/auth.model';
import { DatoPersonaFisicaService } from '../../../controllers/dato.persona.fisica.service';
import { DatoPersonaMoralService } from '../../../controllers/dato.persona.moral.service';
import { EventoCobroAsignacionService } from '../../../controllers/evento.cobro.asignacion.service';
import { EventoCobroAsignacion } from '../../../models/evento.cobro.asignacion';

@Component({
  selector: 'app-estado-cuenta2',
  imports: [
    FormsModule,
    ViewResumenCreditoComponent,
    ViewPeriodosComponent,
    ViewRelacionAbonosComponent,
    ViewGestionesCobroComponent,
    ViewResumenClienteComponent,
    ViewRelacionConveniosComponent,
    EjecucionCobroComponent,
    BuscadorCreditosComponent,
    CollapsableComponent,
    RouterLink,
  ],
  templateUrl: './estado-cuenta2.component.html',
  styleUrl: './estado-cuenta2.component.css',
})
export class EstadoCuenta2Component {
  credito?: Credito;

  fechaCorte: string = new Date().toISOString().substring(0, 10);

  cobroEdit?: CreditoEventoCobro;
  creditos: Credito[] = [];

  creditoOriginal?: Credito;

  relations: string[] = ['*'];
  user:UsuarioLogin
  permisos?: Permiso[] = [];
  showActions: boolean = false;

  eventoCobroAsignaciones: EventoCobroAsignacion[]=[]

  constructor(
    public utils: UtilsService,
    private creditoController: CreditoService,
    private localStorage: LocalStorageService,
    private router: Router,
    private route: ActivatedRoute,
    private estadoCuentaUtils: UtilsEstadoCuentaService,
    public estadoCuentaPdf: estadoCuenta,
    public datoPersonaFisicaController: DatoPersonaFisicaService,
    public datoPersonaMoralController: DatoPersonaMoralService,
    private eventoCobroAsignacionController :EventoCobroAsignacionService,
  ) {
    this.user= this.localStorage.getUser()
  }

  ngOnInit() {
    this.route.params.subscribe(async (params) => {
      if (params['credito_id']) {
        console.log('set credito from url');
        if (!this.credito || this.credito.id != params['credito_id']) {
          const res = await this.creditoController.find(
            params['credito_id'],
            this.relations,
            false,
          );
          if (res) {
            this.credito = res;
            this.setEstadoCuentaWithFechaCorte();
            this.revisarAsignaciones()
          }
        }
      }
    });
    // -- permisos
    const perfil = this.localStorage.getPerfil();
    this.permisos = (this.localStorage.getPerfil().permisos_usuarios ?? []).filter(pu => pu.permisos !== undefined).map(pu => pu.permisos!)
    this.showActions = this.verificarPermisos();
  }

  private async revisarAsignaciones(){
    this.eventoCobroAsignaciones= await this.eventoCobroAsignacionController.asignacionesPendientes(this.credito)
  }

  public setEstadoCuentaWithFechaCorte() {
    this.creditoOriginal= undefined
    if (!this.credito) return;
    this.credito.estado_cuenta = this.estadoCuentaUtils.calculateEstadoDeCuenta(
      this.credito,
      false,
      this.fechaCorte.substring(0, 10) + 'T17:00:00Z',
    );
    this.credito = { ...this.credito };

    if (this.credito.convenios?.find((c) => c.estatus == 'ACTIVO')) {
      this.creditoOriginal = { ...this.credito };
      this.creditoOriginal.estado_cuenta =
        this.estadoCuentaUtils.getEstadoCuentaPrevioAConvenio(
          this.creditoOriginal,
          this.fechaCorte.substring(0, 10) + 'T17:00:00Z',
        );
      this.creditoOriginal = { ...this.creditoOriginal };
    }
  }

  public updateUrl(credito: Credito) {
    this.setEstadoCuentaWithFechaCorte()
    this.router.navigate(['/main/estado-cuenta', credito.id]);
    if (this.cobroEdit) {
      this.nuevaCobranza(this.cobroEdit.modalidad);
    }
    this.revisarAsignaciones()
  }

  /**
   * Inicia el proceso de creación de una nueva cobranza para el crédito actual.
   *
   * Este método crea un nuevo evento de cobro asociado al crédito seleccionado,
   * utilizando la modalidad de cobro especificada. El evento de cobro se asigna
   * al usuario actual obtenido del almacenamiento local.
   *
   * @param modalidad - La modalidad de cobro a utilizar (por ejemplo, 'efectivo', 'transferencia', etc.).
   * @returns Una promesa que se resuelve cuando el evento de cobro ha sido creado y asignado.
   */
  public async nuevaCobranza(modalidad: CobroModalidad): Promise<void> {
    const usuario = this.obtenerUsuarioActual();
    if (this.cobroEdit && this.cobroEdit.modalidad == modalidad) {
      this.cobroEdit = undefined;
      return;
    }
    this.cobroEdit = {
      id: 0,
      credito_id: this.credito?.id ?? 0,
      modalidad: modalidad,
      usuario_ejecutivo_id: usuario.id,
      resultado: 'NO REALIZADO',
      usuario_id: usuario.id,
      fecha: new Date().toISOString().substring(0, 10),
      comentario: '',
      deleted_at: '',
      created_at: '',
      updated_at: '',
    };
  }

  /**
   * Obtiene el usuario actual desde el almacenamiento local.
   *
   * @returns El usuario actual.
   */
  private obtenerUsuarioActual(): any {
    return this.localStorage.getUser();
  }

  /**
   * Inserta a la lista local de cobros el evento recien guardado y lo vuelve undefined para ocultar el formulario
   */
  public onCobroSaved() {
    this.credito?.credito_evento_cobros?.unshift(
      this.utils.copyOf(this.cobroEdit),
    );
    this.cobroEdit = undefined;
  }

  private verificarPermisos() {
    return (
      this.permisos?.some(
        (permiso) =>
          permiso.nombre === 'EJECUTIVO COBRANZA' ||
          permiso.nombre === 'ENCARGADO COBRANZA',
      ) ?? false
    );
  }
}
