import { Component, Input, SimpleChanges } from '@angular/core';
import { UtilsService } from '../../../services/utils.service';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
import { CurrencyPipe, DatePipe } from '@angular/common';
import { EstadoCuenta as ec2 } from '../../../models/estado.cuenta';
import { ToastService } from '../../../services/toast.service';
import { EstadoCuenta, EstadoCuentaCliente, UtilsEstadoCuentaService } from '../services/utils-estado-cuenta.service';
import { ViewPeriodosComponent } from "../shared/view-periodos/view-periodos.component";


@Component({
    selector: 'app-resumen-estado-cuenta',
    imports: [
    DatePipe,
    CurrencyPipe,
    RouterLink,
    DatePipe,
    ViewPeriodosComponent
],
    templateUrl: './resumen-estado-cuenta.component.html',
    styleUrl: './resumen-estado-cuenta.component.css'
})
export class ResumenEstadoCuentaComponent {
  @Input() credito?: Credito

  estadoCuenta?: EstadoCuentaCliente

  today = new Date().toISOString()

  showCondonacion: boolean = false
  detalleKeys = [
    'vencimiento',
    'capital',
    'interes_moratorio',
    'interes_normal',
    'adeudo_total',
  ]

  convenioTiposTransform: any = {
    'PAGO': 'CONVENIO DE PAGO',
    'EXTRAJUDICIAL': 'CONVENIO EXTRAJUDICIAL',
    'JUDICIAL': 'CONVENIO JUDICIAL',
    'REESTRUCTURA': 'CONVENIO DE REESTRUCTURA',
  }

  constructor(
    public creditoController: CreditoService,
    private route: ActivatedRoute,
    public utils: UtilsService,
    private utilsEstadoCuenta: UtilsEstadoCuentaService,
  ) { }

  ngOnInit() {
    this.route.paramMap.subscribe(async (params) => {
      const credito_id = this.utils.intOrNull(params.get('credito_id'))
      if (credito_id) {
        this.credito = await this.creditoController.find(credito_id, [
          'estadoCuenta',
          'datosPersonaFisica.negocios',
          'datosPersonaFisica.datosPersonales.ciudades',
          'datosPersonasMorales.ciudades',
          'productosFinancieros.plazos',
          'inversionesProgramas',
          'abonos',
          'creditosPagos',
        ], false)
      }
    })
  }

  ngOnChanges(changes:SimpleChanges){
    if(changes['credito'] && this.credito){
      this.creditoController.parseDetalleEstadoCuenta(this.credito!)
      this.estadoCuenta= this.utilsEstadoCuenta.getEstadoCuentaCliente(this.credito)
      console.log(this.credito)
    }
  }

  totalAbonos(): number {
    return this.credito?.abonos?.reduce((acc, item) => {
      return acc + item.monto
    }, 0) ?? 0
  }
}
