import { Component, Input, SimpleChanges } from '@angular/core';
import { UtilsService } from '../../../../services/utils.service';
import { Credito } from '../../../../models/credito.model';
import { DatoPersonaFisica } from '../../../../models/dato.persona.fisica.model';
import { DatoPersonaMoral } from '../../../../models/dato.persona.moral.model';
import { DatePipe } from '@angular/common';
import { DatoPersonal } from '../../../../models/dato.personal.model';
import { DatoPersonaMoralService } from '../../../../controllers/dato.persona.moral.service';
import { DomiciliosRegistradosComponent } from '../../../cobranza/ejecucion-cobro/domicilios-registrados/domicilios-registrados.component';
import { CreditoService } from '../../../../controllers/credito.service';

@Component({
  selector: 'app-view-resumen-cliente',
  imports: [DatePipe, DomiciliosRegistradosComponent],
  templateUrl: './view-resumen-cliente.component.html',
  styleUrl: './view-resumen-cliente.component.css',
})

/**
 * Componente para mostrar un resumen del cliente, incluyendo información personal,
 * historial de domicilios, referencias personales y más.
 */
export class ViewResumenClienteComponent {
  @Input() credito!: Credito; // Input que recibe un objeto de tipo Credito

  personaFisica?: DatoPersonaFisica | null; // Información de la persona física asociada al crédito
  personaMoral?: DatoPersonaMoral | null; // Información de la persona moral asociada al crédito
  personaFisicaHistory: DatoPersonal[] = []; // Historial de datos personales de la persona física
  personasMoralHistory: DatoPersonaMoral[] = []; // Historial de datos de la persona moral
  aval?: DatoPersonal; // Información del aval asociado al crédito
  representanteLegal?: DatoPersonal; /** Información del representante legal de la persona moral */

  // Lista de pestañas disponibles en la interfaz
  tabs = [
    'Cliente',
    'Aval',
    'Referencias Personales',
    'Ubicaciones Registradas',
    'Historial De Domicilios',
  ];
  tabSelected = 'Cliente'; // Pestaña seleccionada por defecto
  constructor(
    public creditoController: CreditoService,
    public utils: UtilsService, // Servicio de utilidades
    private personaMoralController: DatoPersonaMoralService, // Servicio para manejar datos de personas morales
  ) {}

  telefonos: string[] = [];
  telefonosString = '';
  emails: string[] = [];

  /**
   * Método que se ejecuta al detectar cambios.
   * Carga la información del cliente, aval y el historial de domicilios.
   */
  async ngOnChanges(changes: SimpleChanges) {
    if (changes['credito']) {
      this.initializeData();
      await this.checkIfIsReestructura();
      this.loadClientData();
      this.loadAvalData();
      this.loadRepresentanteLegalData();
      this.loadPersonaFisicaHistory();
      this.loadPersonaMoralHistory();
      this.adjustTabsBasedOnClientType();
      this.loadTelefonos();

      console.log('Resumen Cliente', this.credito);
    }
  }

  private initializeData() {
    this.personaFisica = undefined;
    this.personaMoral = undefined;
    this.aval = undefined;
    this.representanteLegal = undefined;
    this.personaFisicaHistory = [];
    this.personasMoralHistory = [];
  }

  private loadTelefonos() {
    if (this.credito.datos_personas_morales?.telefonos) {
      this.telefonos = [
        ...this.credito.datos_personas_morales.telefonos.map((t) => t.numero),
      ];
    }else if (
      this.credito.datos_persona_fisica?.datos_personales &&
      this.credito.datos_persona_fisica.datos_personales.telefonos_personales
    ) {
      this.telefonos = [
        ...this.credito.datos_persona_fisica.datos_personales.telefonos_personales.map(
          (t) => t.numero,
        ),
      ];
    }

    this.telefonos = Array.from(new Set(this.telefonos));
    this.telefonosString = this.telefonos.join(', ');
  }

  private async checkIfIsReestructura() {
    if (
      !this.credito.datos_persona_fisica &&
      !this.credito.datos_personas_morales &&
      this.credito.folio
    ) {
      const reestructura = await this.creditoController.first(
        {
          folio_reestructura: this.credito.folio,
        },
        ['*'],
        {},
        false,
      );
      if (reestructura) {
        this.credito = reestructura;
      }
    }
  }

  /**
   * Carga los datos del cliente (persona física o moral) desde el objeto Credito.
   */
  private loadClientData() {
    this.personaFisica = this.credito.datos_persona_fisica;
    this.personaMoral = this.credito.datos_personas_morales;
  }

  /**
   * Carga los datos del aval desde el objeto Credito.
   */
  private loadAvalData() {
    this.aval = this.credito.datos_personales;
  }

  private loadRepresentanteLegalData() {
    this.representanteLegal = this.personaMoral?.representante_legal;
  }

  /**
   * Carga el historial de datos personales de la persona física.
   */
  private loadPersonaFisicaHistory() {
    this.personaFisicaHistory =
      this.personaFisica?.datos_personales?.history ?? [];
  }

  /**
   * Carga el historial de datos de la persona moral.
   */
  private async loadPersonaMoralHistory() {
    if (!this.personaMoral) return;
    this.personasMoralHistory = await this.personaMoralController.all(
      { rfc: this.personaMoral.rfc, deleted_at: null },
      [],
      {},
      false,
    );
  }

  /**
   * Ajusta las pestañas disponibles en la interfaz según el tipo de cliente (persona física o moral).
   */
  private adjustTabsBasedOnClientType() {
    this.tabSelected = 'Cliente';
    if (this.personaMoral) {
      this.tabs = [
        'Cliente',
        'Aval',
        'Representante Legal',
        'Referencias Personales',
        'Ubicaciones Registradas',
        'Historial De Domicilios',
      ];
    }
    if (this.personaFisica) {
      this.tabs = [
        'Cliente',
        'Aval',
        'Referencias Personales',
        'Ubicaciones Registradas',
        'Historial De Domicilios',
      ];
    }
  }
}
