import { Component, Input, SimpleChanges } from '@angular/core';
import { CreditoEventoCobro } from '../../../../models/credito.evento.cobro';
import { CreditoService } from '../../../../controllers/credito.service';
import { Credito } from '../../../../models/credito.model';
import { TablaLocalComponent } from "../../../../shared/tabla-local/tabla-local.component";

import { TableBootstrapComponent } from "../../../../shared/table-bootstrap/table-bootstrap.component";
import { UtilsService } from '../../../../services/utils.service';
import { TitlecasePipe } from '../../../../pipes/titlecase.pipe';
import { VerificacionCredito } from '../../../../models/verificacion.credito.model';
import { RouterLink } from '@angular/router';
import { LeafletComponent } from "../../../../shared/leaflet/leaflet.component";

@Component({
    selector: 'app-domicilios-registrados',
    imports: [
    TableBootstrapComponent,
    LeafletComponent
],
    templateUrl: './domicilios-registrados.component.html',
    styleUrl: './domicilios-registrados.component.css'
})
export class DomiciliosRegistradosComponent {
  @Input() credito_id?: number
  credito?:Credito
  verificaciones:VerificacionCredito[]=[]

  showDetailed:boolean=false
  detailed?:VerificacionCredito

  constructor(
    private creditoController:CreditoService,
    public utils: UtilsService,
  ){}

  async ngOnChanges(changes:SimpleChanges){
    if(changes['credito_id'] && this.credito_id){
      this.credito= await this.creditoController.find(this.credito_id, ['verificaciones'],false)
      this.verificaciones= (this.credito?.verificaciones??[]).
      filter((verif)=> verif.latitud_domicilio && verif.longitud_domicilio)
    }
  }

  detail(verif:VerificacionCredito){
    this.detailed=verif
    this.showDetailed=true
  }
}
