import { Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { FormularioFlotanteComponent } from "../../../../shared/formulario-flotante/formulario-flotante.component";
import { FormsModule } from '@angular/forms';
import { CreditoCondonacionMoratorio } from '../../../../models/credito.condonacion.moratorio';
import { CreditoCondonacionMoratorioService } from '../../../../controllers/credito.condonacion.moratorio.service';

@Component({
    selector: 'app-form-condonacion-moratorio',
    imports: [
        FormularioFlotanteComponent,
        FormsModule,
    ],
    templateUrl: './form-condonacion-moratorio.component.html',
    styleUrl: './form-condonacion-moratorio.component.css'
})
export class FormCondonacionMoratorioComponent {
  @Input() show:boolean=false
  @Output() showChange= new EventEmitter<boolean>()
  @Input() credito_id?:number
  condonacion: CreditoCondonacionMoratorio={
    credito_id: 0,
    monto: 0,
    descuento_pagos_juridico: 'NO',
    motivo: '',
    id: 0,
    deleted_at: null,
    created_at: '',
    updated_at: null
  }

  constructor(
    private condonacionController: CreditoCondonacionMoratorioService,
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(changes['show'] && this.show){
      this.condonacion={
        credito_id: 0,
        monto: 0,
        descuento_pagos_juridico: 'NO',
        motivo: '',
        id: 0,
        deleted_at: null,
        created_at: '',
        updated_at: null
      }
    }
  }

  async submit(){
    if(!this.credito_id ) return
    this.condonacion.credito_id=this.credito_id
    const res =await this.condonacionController.new(this.condonacion)
    if(res){
      this.show=false
      this.showChange.emit(this.show)
    }

  }
}
