import { Component } from '@angular/core';
import { TablaComponent, TableDefinition } from "../../../../shared/tabla/tabla.component";
import { CreditoCondonacionMoratorioService } from '../../../../controllers/credito.condonacion.moratorio.service';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../../services/utils.service';
import { FormCondonacionMoratorioComponent } from '../form-condonacion-moratorio/form-condonacion-moratorio.component';

const TABLA_DEF:TableDefinition={
  columns:[
    'id',
    {
      key:'monto',
      header:'Monto',
      pipe:'currency',
    },
    'descuento_pagos_juridico',
    'motivo',
    {
      key:'usuarios',
      subKey:'nombre',
      header:'Creado Por'
    },
    'created_at',
    'deleted_at',
  ]
}

@Component({
    selector: 'app-list-condonacion-moratorio',
    imports: [
        TablaComponent,
        FormCondonacionMoratorioComponent,
    ],
    templateUrl: './list-condonacion-moratorio.component.html',
    styleUrl: './list-condonacion-moratorio.component.css'
})
export class ListCondonacionMoratorioComponent {
  credito_id:number=0
  tabla= TABLA_DEF
  showAdd:boolean=false
  constructor(
    public condonacionController: CreditoCondonacionMoratorioService,
    private route: ActivatedRoute,
    private utils: UtilsService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe((params)=>{
      this.credito_id= this.utils.intOrNull(params.get('credito_id'))??0
      console.log(this.credito_id)
    })  
  }
}
